import 'dart:async';
import 'package:flutter/foundation.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import 'dual_sync_service.dart';

/// Default device this app talks to until a real device-picker/
/// provisioning flow exists. Matches the bootstrap row created by
/// supabase_setup_v4.sql's claim_default_device() trigger.
const String kDefaultDeviceId = 'ESP32-001';

/// Represents one PTZ command generated by the Flutter joystick.
class PtzCommand {
  final double pan;
  final double tilt;
  final double speed;
  final String mode;
  final String? presetName;

  const PtzCommand({
    required this.pan,
    required this.tilt,
    required this.speed,
    this.mode = 'manual',
    this.presetName,
  });

  Map<String, dynamic> toMap(String deviceId) => {
        'device_id': deviceId,
        'user_id': Supabase.instance.client.auth.currentUser?.id,
        'pan': pan,
        'tilt': tilt,
        'speed': speed,
        'mode': mode,
        if (presetName != null) 'preset_name': presetName,
        'status': 'created',
      };
}

/// Live servo/PTZ feedback reported back by the ESP32-S3 via ptz_state.
class PtzState {
  final double panPosition;
  final double tiltPosition;
  final bool moving;
  final bool autoTracking;
  final DateTime updatedAt;

  const PtzState({
    required this.panPosition,
    required this.tiltPosition,
    required this.moving,
    required this.autoTracking,
    required this.updatedAt,
  });

  factory PtzState.fromMap(Map<String, dynamic> m) => PtzState(
        panPosition: (m['pan_position'] as num?)?.toDouble() ?? 0,
        tiltPosition: (m['tilt_position'] as num?)?.toDouble() ?? 0,
        moving: m['moving'] as bool? ?? false,
        autoTracking: m['auto_tracking'] as bool? ?? false,
        updatedAt: DateTime.tryParse(m['updated_at'] as String? ?? '') ?? DateTime.now(),
      );

  /// True once we've heard from the device recently — used to show
  /// "PTZ ● READY" vs "PTZ ● NO RESPONSE" instead of assuming success.
  bool get isFresh => DateTime.now().difference(updatedAt) < const Duration(seconds: 15);
}

/// PTZ transport: Flutter joystick -> Supabase ptz_commands -> ESP32-S3,
/// and ESP32-S3 -> Supabase ptz_state -> Flutter for live feedback.
///
/// IMPORTANT — what this class does and does not guarantee:
/// It reliably WRITES commands to Supabase and reliably LISTENS for
/// state updates. Whether a command actually reaches a physical servo
/// depends entirely on the ESP32-S3 firmware being online and running
/// the corresponding command-listener task. Until that firmware is
/// flashed and verified, [state] will simply stay stale/absent — the
/// UI should read [connected] rather than assume success.
class PtzService extends ChangeNotifier {
  PtzService._();
  static final PtzService instance = PtzService._();

  final String deviceId = kDefaultDeviceId;

  PtzCommand _last = const PtzCommand(pan: 0, tilt: 0, speed: 0);
  PtzState? _state;
  Timer? _throttle;
  StreamSubscription? _stateSub;

  PtzCommand get lastCommand => _last;
  PtzState? get state => _state;

  /// True only when the ESP32-S3 has reported ptz_state within the
  /// last 15s — i.e. actual hardware presence, not just "UI is open".
  bool get connected => _state?.isFresh ?? false;

  void startListening() {
    _stateSub?.cancel();
    _stateSub = Supabase.instance.client
        .from('ptz_state')
        .stream(primaryKey: ['device_id'])
        .eq('device_id', deviceId)
        .listen((rows) {
      if (rows.isEmpty) return;
      _state = PtzState.fromMap(rows.first);
      notifyListeners();
    }, onError: (e) => debugPrint('PtzService state stream: $e'));
  }

  void stopListening() {
    _stateSub?.cancel();
    _stateSub = null;
  }

  void updateLocal(PtzCommand command) {
    _last = command;
    notifyListeners();
  }

  Future<void> send(PtzCommand command) async {
    updateLocal(command);

    // Throttle so a dragging joystick doesn't flood Realtime with a
    // row per pointer-move event.
    _throttle?.cancel();
    _throttle = Timer(const Duration(milliseconds: 70), () async {
      try {
        final createdAt = DateTime.now().toUtc().toIso8601String();
        final payload = <String, dynamic>{
          ...command.toMap(deviceId),
          'created_at': createdAt,
        };
        await Supabase.instance.client.from('ptz_commands').insert(payload);
        await DualSyncService.instance.writeMirror(
          recordType: 'ptz_commands',
          recordKey: '${deviceId}_$createdAt',
          payload: payload,
        );
      } catch (e) {
        // The UI stays usable even if the table isn't provisioned yet
        // (e.g. supabase_setup_v4.sql hasn't been run) or the device
        // is offline. Command delivery is best-effort by design —
        // physical movement is never assumed from this call alone.
        debugPrint('PTZ command insert failed: $e');
      }
    });
  }

  Future<void> stop() => send(const PtzCommand(pan: 0, tilt: 0, speed: 0, mode: 'stop'));
  Future<void> home() => send(const PtzCommand(pan: 0, tilt: 0, speed: 1, mode: 'home'));
  Future<void> preset(String name) => send(PtzCommand(pan: 0, tilt: 0, speed: 1, mode: 'preset', presetName: name));

  /// Toggling this in the Camera screen used to only flip a local UI
  /// bool — it never actually reached the device. This writes the
  /// real ptz_state.auto_tracking column, which the firmware checks
  /// before doing any PIR-triggered movement.
  Future<void> setAutoTracking(bool enabled) async {
    try {
      final updatedAt = DateTime.now().toUtc().toIso8601String();
      final payload = <String, dynamic>{
        'device_id': deviceId,
        'auto_tracking': enabled,
        'updated_at': updatedAt,
      };
      await Supabase.instance.client.from('ptz_state').upsert(payload);
      await DualSyncService.instance.writeMirror(
        recordType: 'ptz_state',
        recordKey: deviceId,
        payload: payload,
      );
    } catch (e) {
      debugPrint('PTZ setAutoTracking failed: $e');
    }
  }

  void disposeService() {
    _throttle?.cancel();
    _stateSub?.cancel();
  }
}
